"""API fundamentals: RESTful endpoint design with FastAPI and Pydantic models."""
from __future__ import annotations

from fastapi import FastAPI, HTTPException, status
from pydantic import BaseModel, Field
from typing import Optional
import uvicorn

app = FastAPI(
    title="CodetyHub Student API",
    description="REST API for student skill scores",
    version="1.0.0",
)

# In-memory store (replace with DB in production)
_SCORES: dict[str, dict[str, float]] = {}


class SkillScoreIn(BaseModel):
    skill_node: str = Field(..., min_length=1, description="Skill DAG node ID")
    score: float = Field(..., ge=0.0, le=100.0, description="Score out of 100")


class SkillScoreOut(BaseModel):
    student_id: str
    skill_node: str
    score: float


@app.get("/health")
def health_check() -> dict:
    """Service health check."""
    return {"status": "ok", "service": "CodetyHub Student API"}


@app.post("/students/{student_id}/scores",
          response_model=SkillScoreOut,
          status_code=status.HTTP_201_CREATED)
def record_score(student_id: str, body: SkillScoreIn) -> SkillScoreOut:
    """Record or update a student's skill score."""
    _SCORES.setdefault(student_id, {})[body.skill_node] = body.score
    return SkillScoreOut(student_id=student_id,
                          skill_node=body.skill_node, score=body.score)


@app.get("/students/{student_id}/scores",
         response_model=list[SkillScoreOut])
def get_scores(student_id: str, skill_node: Optional[str] = None) -> list[SkillScoreOut]:
    """Retrieve all scores for a student, optionally filtered by skill."""
    if student_id not in _SCORES:
        raise HTTPException(status_code=404, detail="Student not found")
    scores = _SCORES[student_id]
    if skill_node:
        if skill_node not in scores:
            raise HTTPException(status_code=404, detail="Skill not found")
        scores = {skill_node: scores[skill_node]}
    return [SkillScoreOut(student_id=student_id, skill_node=k, score=v)
            for k, v in scores.items()]


if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8080)

