"""Pandas fundamentals: DataFrame creation, filtering, grouping, and aggregation."""
import pandas as pd
import numpy as np


def summarise_dataframe(df: pd.DataFrame) -> pd.DataFrame:
    """Return summary statistics for numeric columns."""
    return df.describe().T[["mean", "std", "min", "max"]]


def top_n_by_column(df: pd.DataFrame, col: str, n: int = 5) -> pd.DataFrame:
    """Return the top N rows sorted by col descending."""
    if col not in df.columns:
        raise KeyError(f"Column '{col}' not found in DataFrame")
    return df.nlargest(n, col)


