def relu(z: np.ndarray) -> np.ndarray:
    return np.maximum(0, z)


def relu_grad(z: np.ndarray) -> np.ndarray:
    return (z > 0).astype(float)


def softmax(z: np.ndarray) -> np.ndarray:
    e = np.exp(z - z.max(axis=1, keepdims=True))
    return e / e.sum(axis=1, keepdims=True)


class MLP:
    """Minimal two-layer MLP with ReLU activations and softmax output."""

    def __init__(self, input_dim: int, hidden_dim: int, output_dim: int,
                  lr: float = 0.01) -> None:
        rng = np.random.default_rng(42)
        scale = np.sqrt(2 / input_dim)
        self.W1 = rng.standard_normal((input_dim, hidden_dim)) * scale
        self.b1 = np.zeros(hidden_dim)
        self.W2 = rng.standard_normal((hidden_dim, output_dim)) * np.sqrt(2 / hidden_dim)
        self.b2 = np.zeros(output_dim)
        self.lr = lr

    def forward(self, X: np.ndarray) -> np.ndarray:
        self.z1 = X @ self.W1 + self.b1
        self.a1 = relu(self.z1)
        self.z2 = self.a1 @ self.W2 + self.b2
        return softmax(self.z2)

    def loss(self, y_prob: np.ndarray, y_true: np.ndarray) -> float:
        eps = 1e-9
        return float(-np.mean(np.log(y_prob[np.arange(len(y_true)), y_true] + eps)))


if __name__ == "__main__":
    rng = np.random.default_rng(0)
    X = rng.standard_normal((200, 8))
    y = rng.integers(0, 3, 200)
    mlp = MLP(input_dim=8, hidden_dim=16, output_dim=3)
    probs = mlp.forward(X)
    print(f"Output shape: {probs.shape}  |  Loss: {mlp.loss(probs, y):.4f}")

