"""Linear algebra: vectors, dot products, norms, and matrix operations."""
import numpy as np


def cosine_similarity(a: np.ndarray, b: np.ndarray) -> float:
    """Compute cosine similarity between two vectors."""
    norm_a, norm_b = np.linalg.norm(a), np.linalg.norm(b)
    if norm_a == 0 or norm_b == 0:
        raise ValueError("Zero vector has undefined cosine similarity")
    return float(np.dot(a, b) / (norm_a * norm_b))


def gram_schmidt(vectors: list[np.ndarray]) -> list[np.ndarray]:
    """Orthonormalise a list of vectors using Gram-Schmidt."""
    orthonormal = []
    for v in vectors:
        v = v.astype(float).copy()
        for u in orthonormal:
            v -= np.dot(v, u) * u
        norm = np.linalg.norm(v)
        if norm > 1e-10:
            orthonormal.append(v / norm)
    return orthonormal


if __name__ == "__main__":
    a = np.array([1.0, 2.0, 3.0])
    b = np.array([4.0, 5.0, 6.0])
    print(f"Cosine similarity: {cosine_similarity(a, b):.4f}")
    vecs = [np.array([3.0, 1.0]), np.array([2.0, 2.0])]
    ortho = gram_schmidt(vecs)
    print("Orthonormal basis:", [v.round(4) for v in ortho])

