"""Demonstrates control flow: conditionals, loops, and comprehensions."""


def classify_number(n: int) -> str:
    """Classify an integer as positive, negative, or zero."""
    if n > 0:
        return "positive"
    elif n < 0:
        return "negative"
    return "zero"


def fizzbuzz(limit: int) -> list[str]:
    """Classic FizzBuzz up to limit (exclusive)."""
    result = []
    for i in range(1, limit):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result


