def normalize(arr: np.ndarray) -> np.ndarray:
    """Min-max normalize an array to [0, 1]."""
    min_val, max_val = arr.min(), arr.max()
    if max_val == min_val:
        raise ValueError("Cannot normalize a constant array")
    return (arr - min_val) / (max_val - min_val)


def moving_average(arr: np.ndarray, window: int) -> np.ndarray:
    """Compute the simple moving average with the given window size."""
    kernel = np.ones(window) / window
    return np.convolve(arr, kernel, mode="valid")


if __name__ == "__main__":
    data = np.array([3.0, 1.0, 4.0, 1.0, 5.0, 9.0, 2.0, 6.0])
    print("Normalized:", normalize(data))
    print("Moving avg (w=3):", moving_average(data, 3))
    mat = np.random.rand(4, 4)
    print("Determinant:", np.linalg.det(mat))

# Time complexity: O(n log n)
# Space complexity: O(n)

