"""Tokenisation: word-level, subword (BPE sketch), and HuggingFace tokeniser demo."""
import re
from collections import defaultdict
from typing import Sequence


def word_tokenize(text: str) -> list[str]:
    """Simple regex word tokeniser preserving punctuation as separate tokens."""
    return re.findall(r"\w+|[^\w\s]", text)


def build_bpe_vocab(corpus: Sequence[str], num_merges: int = 10) -> dict[str, int]:
    """
    Minimal Byte Pair Encoding (BPE) vocabulary builder.

    Args:
        corpus:     List of training sentences.
        num_merges: Number of merge operations to perform.

    Returns:
        Token frequency dict after merges.
    """
    # Represent each word as characters separated by spaces, ending with </w>
    vocab: dict[str, int] = defaultdict(int)
    for sentence in corpus:
        for word in sentence.lower().split():
            vocab[" ".join(list(word)) + " </w>"] += 1

    for _ in range(num_merges):
        pairs: dict[tuple[str, str], int] = defaultdict(int)
        for word, freq in vocab.items():
            symbols = word.split()
            for i in range(len(symbols) - 1):
                pairs[(symbols[i], symbols[i + 1])] += freq
        if not pairs:
            break
        best = max(pairs, key=pairs.get)  # type: ignore[arg-type]
        bigram = re.escape(" ".join(best))
        new_vocab = {re.sub(bigram, "".join(best), w): v for w, v in vocab.items()}
        vocab = new_vocab  # type: ignore[assignment]

    return dict(sorted(vocab.items(), key=lambda x: -x[1]))


# Entry point
if __name__ == "__main__":
    sample = "the quick brown fox jumps over the lazy dog"
    print("Word tokens:", word_tokenize(sample))

    corpus = ["low lower newest widest"] * 5 + ["lower new wide"] * 3
    bpe_vocab = build_bpe_vocab(corpus, num_merges=5)
    print("\nBPE vocab (top 10):")
    for token, freq in list(bpe_vocab.items())[:10]:
        print(f"  {token!r:30s}  freq={freq}")

